export function Microinteraction({
  checked = {{checked}},
  duration = {{duration}},
  task = "{{task}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span className="check" style={{ width: 20, height: 20, borderRadius: 5, border: `2px solid ${checked ? accent : "#24143044"}`, background: checked ? accent : "transparent", display: "grid", placeItems: "center", flex: "none" }}>
          <svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path style={{ opacity: checked ? 1 : 0 }} fill="none" stroke="#fff" strokeWidth="2" d="M3 8l3 3 7-7" /></svg>
        </span>
        <span style={{ color: "#241430", textDecoration: checked ? "line-through" : "none" }}>{task}</span>
      </div>
      <p style={{ margin: "12px 0 0" }}>A microinteraction: one small task, one small acknowledgement</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .check { transition: background ${duration}ms ease-out, border-color ${duration}ms ease-out; }
          .check svg path { transition: opacity ${duration}ms ease-out; }
        }
      `}</style>
    </div>
  );
}
